    /// Creates a new, empty scope.
    pub fn new() -> Self {
        Self {
            columns: Vec::new(),
            tables: HashSet::new(),
            qualified: HashMap::new(),
            unqualified: HashMap::new(),
            aggregates: HashMap::new(),
            hidden: HashSet::new(),
        }
    }

    /// Creates a scope from a table, using the table's original name.
    fn from_table(table: &Table) -> Result<Self> {
        let mut scope = Self::new();
        scope.add_table(table, None)?;
        Ok(scope)
    }

    /// Creates a new child scope that inherits from the parent scope.
    pub fn spawn(&self) -> Self {
        Self {
            columns: self.columns.clone(),
            tables: self.tables.clone(),
            qualified: self.qualified.clone(),
            unqualified: self.unqualified.clone(),
            aggregates: self.aggregates.clone(),
            hidden: self.hidden.clone(),
        }
    }

    /// Adds a table to the scope.
    fn add_table(&mut self, table: &Table, alias: Option<&str>) -> Result<()> {
        let name = alias.unwrap_or(&table.name);
        if self.tables.contains(name) {
            return Err(errinput!("duplicate table name: {}", name));
        }
        self.tables.insert(name.to_string());
        for (i, col) in table.columns.iter().enumerate() {
            let label = Label::Qualified(name.to_string(), col.name.clone());
            let idx = self.add_column(label);
            self.qualified
                .insert((name.to_string(), col.name.clone()), idx);
            self.unqualified
                .entry(col.name.clone())
                .or_insert_with(Vec::new)
                .push(idx);
        }
        Ok(())
    }

    /// Appends a column with the given label to the scope.
    fn add_column(&mut self, label: Label) -> usize {
        let idx = self.columns.len();
        self.columns.push(label);
        idx
    }

    /// Looks up a column index by name, if possible.
    fn lookup_column(&self, table: Option<&str>, name: &str) -> Result<usize> {
        if let Some(table) = table {
            if let Some(&idx) = self.qualified.get(&(table.to_string(), name.to_string())) {
                return Ok(idx);
            }
        }
        if let Some(indices) = self.unqualified.get(name) {
            if indices.len() == 1 {
                return Ok(indices[0]);
            }
            return Err(errinput!("ambiguous column: {}", name));
        }
        Err(errinput!("unknown column: {}", name))
    }

    /// Adds an aggregate expression to the scope.
    fn add_aggregate(&mut self, expr: &ast::Expression, parent: &Scope) -> Option<usize> {
        if let ast::Expression::Operator(ast::Operator::Function(name, args)) = expr {
            if let Some(idx) = parent.aggregates.get(expr) {
                return Some(*idx);
            }
            let idx = self.add_column(Label::None);
            self.aggregates.insert(expr.clone(), idx);
            Some(idx)
        } else {
            None
        }
    }

    /// Looks up an aggregate column index by aggregate function or GROUP BY
    /// expression.
    fn lookup_aggregate(&self, expr: &ast::Expression) -> Option<usize> {
        self.aggregates.get(expr).copied()
    }

    /// Adds a column that passes through a column from the parent scope.
    fn add_passthrough(&mut self, parent: &Scope, parent_index: usize, hide: bool) -> usize {
        let label = parent.columns[parent_index].clone();
        let idx = self.add_column(label);
        if hide {
            self.hidden.insert(idx);
        }
        idx
    }

    /// Merges two scopes, by appending the given scope to self.
    fn merge(&mut self, scope: Scope) -> Result<()> {
        for (i, label) in scope.columns.into_iter().enumerate() {
            let idx = self.add_column(label);
            if let Label::Qualified(table, column) = &label {
                self.qualified.insert((table.clone(), column.clone()), idx);
            }
            if let Label::Unqualified(column) = &label {
                self.unqualified
                    .entry(column.clone())
                    .or_insert_with(Vec::new)
                    .push(idx);
            }
        }
        self.tables.extend(scope.tables);
        self.aggregates.extend(scope.aggregates);
        self.hidden.extend(scope.hidden);
        Ok(())
    }

    /// Projects the scope via the given expressions and aliases.
    fn project(&self, expressions: &[(ast::Expression, Option<String>)]) -> Self {
        let mut result = Self::new();
        for (expr, alias) in expressions {
            let label = alias.as_ref().map(Label::Unqualified).unwrap_or(Label::None);
            let idx = result.add_column(label);
            if let ast::Expression::Operator(ast::Operator::Function(_, _)) = expr {
                result.aggregates.insert(expr.clone(), idx);
            }
        }
        result
    }

    /// Remaps the scope using the given targets.
    fn remap(&self, targets: &[Option<usize>]) -> Self {
        let mut result = Self::new();
        for target in targets {
            if let Some(idx) = target {
                let label = self.columns[*idx].clone();
                let new_idx = result.add_column(label);
                if let Label::Qualified(table, column) = &label {
                    result.qualified.insert((table.clone(), column.clone()), new_idx);
                }
                if let Label::Unqualified(column) = &label {
                    result
                        .unqualified
                        .entry(column.clone())
                        .or_insert_with(Vec::new)
                        .push(new_idx);
                }
            }
        }
        result
    }

    /// Removes hidden columns from the scope.
    fn remove_hidden(&mut self) -> Option<HashSet<usize>> {
        let hidden = self.hidden.clone();
        self.columns.retain(|_| !self.hidden.is_empty());
        self.hidden.clear();
        Some(hidden)
    }

    /// Removes hidden columns from the scope and returns the remaining column
    /// indexes as a Remap targets vector.
    fn remap_hidden(&mut self) -> Option<Vec<Option<usize>>> {
        let hidden = self.hidden.clone();
        let mut result = Vec::with_capacity(self.columns.len());
        for (i, _) in self.columns.iter().enumerate() {
            if hidden.contains(&i) {
                result.push(None);
            } else {
                result.push(Some(i));
            }
        }
        self.columns.retain(|_| !self.hidden.is_empty());
        self.hidden.clear();
        Some(result)
    }
}
